@import "@fontsource-variable/mona-sans/wdth.css";
@import "./tokens.css";

*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--void);
  color: var(--ink);
  font-family: var(--font);
  font-size: var(--t-body);
  line-height: 1.45;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-variant-numeric: tabular-nums;
}
::selection { background: rgba(77, 148, 255, 0.4); color: #fff; }
:focus { outline: none; }
:focus-visible { outline: 1px solid var(--sweep-hi); outline-offset: 3px; border-radius: 4px; }
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
a { color: var(--sweep-hi); text-underline-offset: 3px; }
h1, h2, h3, p { margin: 0; }
* { scrollbar-width: thin; scrollbar-color: var(--hair-2) transparent; }

/* the instrument numeral: wide, light, tabular */
.num { font-stretch: 118%; font-weight: 300; letter-spacing: -0.02em; line-height: 1; font-variant-numeric: tabular-nums; }
.label { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.02em; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

content.content:
.scan { position: fixed; inset: 0; background: var(--void); }
.scan-canvas { position: absolute; inset: 0; }
.scan-canvas canvas { display: block; }
.scan-state { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 14px; color: var(--ink-3); font-size: var(--t-label); letter-spacing: 0.08em; }
.scan-state.error { color: var(--lost); max-width: 48ch; text-align: center; margin: auto; letter-spacing: 0; }
.scan-pulse { width: 64px; height: 64px; border-radius: 50%; border: 1px solid var(--hair-2); position: relative; }
.scan-pulse::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border-top: 1px solid var(--sweep-hi); animation: spin 1.4s linear infinite; }
@keyframes spin { to { transform: rotate(1turn); } }

/* readout: three peer numerals, top-left */
.readout { position: fixed; top: var(--edge); left: var(--edge); z-index: 10; display: flex; gap: 40px; margin: 0; pointer-events: none; }
.readout div { display: grid; gap: 8px; }
.readout dt { display: inline-flex; align-items: center; gap: 7px; }
.readout dd { margin: 0; display: inline-flex; align-items: baseline; gap: 10px; }
.readout .num { font-size: 34px; color: var(--ink); }
.plus { font-size: var(--t-label); font-weight: 600; color: var(--ink-2); letter-spacing: 0.01em; }
.glyph { color: var(--ink-2); flex: none; }
.glyph-trio { display: inline-flex; gap: 1px; }
.ring-name i { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }

/* ring labels drawn in 3D space */
.ring-label { display: grid; justify-items: center; gap: 2px; white-space: nowrap; pointer-events: none; user-select: none; }
.ring-label b { font-size: var(--t-label); font-weight: 600; color: var(--ink-2); }
.ring-label span { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.06em; }
.time-label { font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.1em; color: var(--ink-2); white-space: nowrap; pointer-events: none; user-select: none; }

.ring-name { display: inline-flex; align-items: center; gap: 5px; font-size: var(--t-micro); color: var(--ink-2); letter-spacing: 0.06em; white-space: nowrap; pointer-events: none; user-select: none; padding: 1px 5px; background: rgba(0, 0, 0, 0.7); border-radius: 4px; }

/* key: left edge, filters by isolating */
.key { position: fixed; left: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 10; width: 272px; display: grid; gap: 12px; }
.key-dims { display: flex; flex-wrap: wrap; gap: 2px 12px; }
.key-dims button { font-size: var(--t-label); color: var(--ink-3); padding: 3px 0; border-bottom: 1px solid transparent; transition: color var(--fast), border-color var(--fast); }
.key-dims button:hover { color: var(--ink-2); }
.key-dims button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--sweep-hi); }
.key-values { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.key-values button { width: 100%; display: grid; grid-template-columns: 1fr 64px 52px; align-items: center; gap: 10px; padding: 5px 8px; margin: 0 -8px; border-radius: 6px; text-align: left; transition: background var(--fast), opacity var(--fast); }
.key-values button:hover { background: rgba(255, 255, 255, 0.05); }
.key-values button[data-dim] { opacity: 0.38; }
.key-values button[aria-pressed="true"] .key-name { color: var(--ink); }
.key-name { font-size: var(--t-label); color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.key-bar { height: 2px; background: var(--hair); border-radius: 1px; overflow: hidden; }
.key-bar span { display: block; height: 100%; background: var(--ink-2); transform-origin: 0 50%; transition: transform var(--med) var(--ease); }
.key-values button[aria-pressed="true"] .key-bar span { background: var(--sweep-hi); }
.key-n { font-size: var(--t-label); color: var(--ink-2); text-align: right; font-variant-numeric: tabular-nums; }
.key-clear { justify-self: start; font-size: var(--t-label); color: var(--ink-2); display: inline-flex; gap: 8px; align-items: baseline; }
.key-clear:hover { color: var(--ink); }

/* hover card + comment sheet */
.hovercard { position: fixed; z-index: 30; width: 320px; padding: 12px 14px; border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); pointer-events: none; display: grid; gap: 8px; box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 16px 40px rgba(0, 0, 0, 0.5); }
.hovercard p { font-size: 13px; line-height: 1.45; color: var(--ink); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.hovercard-meta { display: flex; align-items: center; gap: 10px; font-size: var(--t-micro); color: var(--ink-3); }
.sheet { position: fixed; top: var(--edge); right: var(--edge); z-index: 25; width: min(400px, calc(100vw - 32px)); max-height: calc(100vh - 2 * var(--edge) - 150px); overflow: auto; padding: 28px 26px 24px; border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6); display: grid; gap: 22px; animation: sheet-in var(--med) var(--ease); }
@keyframes sheet-in { from { opacity: 0; transform: translateY(-6px); } }
.sheet-close { position: absolute; top: 12px; right: 12px; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--ink-3); transition: background var(--fast), color var(--fast); }
.sheet-close:hover { background: rgba(255, 255, 255, 0.07); color: var(--ink); }
.sheet-head { display: grid; gap: 6px; padding-right: 28px; }
.sheet-layer { display: inline-flex; align-items: center; gap: 8px; font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.sheet-what { font-size: var(--t-label); color: var(--ink-3); max-width: 46ch; }
.sheet-title { font-size: var(--t-read); font-weight: 500; line-height: 1.35; color: var(--ink); text-wrap: balance; }
.sheet-figure { display: flex; align-items: baseline; gap: 12px; }
.sheet-figure .num { font-size: 34px; color: var(--ink); }
.sheet-yoy { font-size: var(--t-body); color: var(--ink-2); }
.sheet-link { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; justify-self: start; }
.zbar { position: relative; height: 30px; }
.zbar-mid { position: absolute; left: 50%; top: 0; height: 12px; width: 1px; background: var(--hair-2); }
.zbar-fill { position: absolute; top: 4px; height: 4px; border-radius: 2px; background: var(--ink); }
.zbar-l, .zbar-r { position: absolute; top: 16px; }
.zbar-l { left: 0; } .zbar-r { right: 0; }
.minibars { display: flex; gap: 22px; align-items: flex-end; }
.minibar { display: grid; gap: 6px; justify-items: center; }
.minibar-n { font-size: var(--t-label); color: var(--ink-2); font-variant-numeric: tabular-nums; }
.minibar-col { width: 26px; height: 96px; display: flex; align-items: flex-end; }
.minibar-col span { width: 100%; height: 100%; background: var(--ink-3); border-radius: 2px 2px 0 0; transform-origin: 50% 100%; }
.minibar[data-on] .minibar-col span { background: var(--ink); }
.minibar[data-on] .minibar-n { color: var(--ink); }
.minibar[data-forecast] .minibar-col span { background: transparent; box-shadow: inset 0 0 0 1px var(--ink-2); }
.sheet-quote { margin: 0; font-size: var(--t-read); line-height: 1.5; color: var(--ink); max-width: 60ch; padding-right: 16px; }
.sheet-facts { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }
.sheet-facts div { display: grid; gap: 3px; min-width: 0; }
.sheet-facts dd { margin: 0; font-size: 13px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.sheet-ref { letter-spacing: 0.08em; }
.sheet-skel { display: grid; gap: 10px; }
.sheet-skel span { height: 12px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); }
.sheet-skel span:last-child { width: 60%; }

@media (max-width: 760px) {
  .readout { gap: 22px; left: 16px; top: 16px; }
  .readout .num { font-size: 24px; }
  .key { bottom: auto; top: 96px; width: calc(100vw - 32px); left: 16px; }
  .key-values { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 4px; }
  .key-values button { margin: 0; grid-template-columns: auto auto; gap: 6px; border: 1px solid var(--hair); border-radius: 99px; padding: 4px 10px; white-space: nowrap; }
  .key-bar { display: none; }
  .sheet { top: auto; bottom: 140px; }
}
.sweepctl {
  position: fixed; right: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 20;
  width: 280px; padding: 16px 18px 14px; border-radius: var(--r);
  background: var(--glass); border: 1px solid var(--hair);
  backdrop-filter: blur(14px) saturate(1.2); -webkit-backdrop-filter: blur(14px) saturate(1.2);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6);
  display: grid; gap: 14px;
}
.sweepctl-track { position: relative; display: flex; justify-content: space-between; align-items: flex-start; }
.sweepctl-line, .sweepctl-fill { position: absolute; left: 6px; right: 6px; top: 6px; height: 1px; }
.sweepctl-line { background: var(--hair-2); }
.sweepctl-fill { background: var(--ink-2); transform-origin: 0 50%; transform: scaleX(0); transition: transform var(--sweep-ms) var(--ease); }
.sweepctl-track[data-cp="cp2"] .sweepctl-fill { transform: scaleX(1); }
.sweepctl-node { position: relative; display: grid; gap: 8px; justify-items: start; padding: 0; border-radius: 6px; }
.sweepctl-node:last-child { justify-items: end; }
.sweepctl-dot {
  width: 13px; height: 13px; border-radius: 50%; background: var(--void); border: 1px solid var(--ink-3);
  transition: background var(--med) var(--ease), border-color var(--med) var(--ease), box-shadow var(--med) var(--ease);
}
.sweepctl-node[data-on] .sweepctl-dot { background: var(--ink); border-color: var(--ink); }
.sweepctl-node[aria-checked="true"] .sweepctl-dot { background: var(--sweep-hi); border-color: var(--sweep-hi); box-shadow: 0 0 0 4px var(--sweep-wash); }
.sweepctl-node[aria-checked="false"]:hover .sweepctl-dot { border-color: var(--ink); }
.sweepctl-name { font-size: var(--t-label); font-weight: 600; letter-spacing: 0.08em; color: var(--ink-3); transition: color var(--fast); }
.sweepctl-node[aria-checked="true"] .sweepctl-name { color: var(--ink); }
.sweepctl-tracks { display: flex; gap: 18px; justify-content: flex-end; font-size: var(--t-body); font-variant-numeric: tabular-nums; }
.sweepctl-tracks > span { display: inline-flex; align-items: center; gap: 7px; }
.sweepctl-tracks .label { margin-left: 2px; }
.mark { display: inline-block; width: 8px; height: 8px; border-radius: 50%; }
.mark.held { background: var(--ink); }
.mark.new { background: transparent; box-shadow: inset 0 0 0 1.5px var(--ink); }
@media (max-width: 560px) { .sweepctl { left: 16px; right: 16px; width: auto; } }
