1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
2	import { Suspense, useEffect, useMemo, useState } from "react";
3	import { Canvas } from "@react-three/fiber";
4	import { useQuery } from "@tanstack/react-query";
5	import { ExternalLink, X } from "lucide-react";
6	import { api } from "@/lib/api";
7	import type { Comment, PointsPayload, Selection, SourcesPayload } from "@/lib/types";
8	import { useCheckpoint } from "@/state/checkpoint";
9	import { Scene, TYPE_COLOR, studyValue, type Hover } from "./Scene";
10	import { CAR_NAME, MARKET_NAME } from "./layout";
11	import "./scan.css";
12	
13	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
14	
15	type Dim = "car" | "market" | "channel" | "type" | "engine";
16	const DIMS: { id: Dim; name: string }[] = [
17	  { id: "car", name: "Car" }, { id: "market", name: "Market" }, { id: "channel", name: "Channel" },
18	  { id: "type", name: "Label" }, { id: "engine", name: "Engine" },
19	];
20	function valueName(dim: Dim, v: string | null): string {
21	  if (v == null) return "Unlabelled";
22	  if (dim === "car") return CAR_NAME[v] ?? v;
23	  if (dim === "market") return MARKET_NAME[v] ?? v;
24	  return v;
25	}
26	
27	export function Scan() {
28	  const { from, sweepId, position, checkpoints } = useCheckpoint();
29	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
30	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
31	  const [dim, setDim] = useState<Dim>("car");
32	  const [isolate, setIsolate] = useState<Set<number>>(new Set());
33	  const [hover, setHover] = useState<Hover | null>(null);
34	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
35	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
36	
37	  const mask = useMemo(() => {
38	    const n = points.data?.n ?? 0;
39	    const m = new Uint8Array(n).fill(1);
40	    if (!points.data || isolate.size === 0) return m;
41	    const col = points.data.cols[dim];
42	    for (let i = 0; i < n; i++) m[i] = isolate.has(col[i]) ? 1 : 0;
43	    return m;
44	  }, [points.data, dim, isolate]);
45	
46	  useEffect(() => {
47	    const onKey = (e: KeyboardEvent) => {
48	      if (e.key !== "Escape") return;
49	      if (selected) setSelected(null); else setIsolate(new Set());
50	    };
51	    window.addEventListener("keydown", onKey);
52	    return () => window.removeEventListener("keydown", onKey);
53	  }, [selected]);
54	
55	  return (
56	    <main className="scan" aria-label="Raw evidence at the selected checkpoint">
57	      <div className="scan-canvas">
58	        {points.data && (
59	          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
60	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
61	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
62	                  onPointerMissed={() => setSelected(null)}>
63	            <Suspense fallback={null}>
64	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
65	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null}
66	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }} />
67	            </Suspense>
68	          </Canvas>
69	        )}
70	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
71	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
72	      </div>
73	
74	      <Readout />
75	
76	      {points.data && (
77	        <Key points={points.data} position={position} dim={dim} isolate={isolate}
78	             onDim={(d) => { setDim(d); setIsolate(new Set()); }}
79	             onToggle={(v) => setIsolate((s) => { const n = new Set(s); n.has(v) ? n.delete(v) : n.add(v); return n; })}
80	             onClear={() => setIsolate(new Set())} />
81	      )}
82	
83	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
84	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)}
85	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
86	    </main>
87	  );
88	}
89	
90	/* ------------------------------------------------------------------------------------------- glyphs */
91	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
92	const GLYPH_COLOR: Record<GlyphKind, string> = {
93	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
94	};
95	function Glyph({ kind }: { kind: GlyphKind }) {
96	  const c = "currentColor";
97	  return (
98	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
99	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
100	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
101	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
102	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
103	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
104	    </svg>
105	  );
106	}
107	
108	/* ------------------------------------------------------------------------------------------- readout */
109	function Readout() {
110	  const { current, position } = useCheckpoint();
111	  const s = current?.sources;
112	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
113	  const internal = s ? s.study.visible + s.option_list.visible + s.sales.visible : undefined;
114	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number }[] = [
115	    { k: "comment", label: "Comments", n: s?.feedback.visible, nu: s?.feedback.new },
116	    { k: "research", label: "Research", n: s?.research.visible, nu: s?.research.new },
117	    { k: "sales", label: "BMW data", n: internal },
118	  ];
119	  return (
120	    <dl className="readout" aria-label="Evidence at this checkpoint">
121	      {cells.map((c) => (
122	        <div key={c.label}>
123	          <dt>{c.k === "sales" ? <span className="glyph-trio"><Glyph kind="study" /><Glyph kind="option" /><Glyph kind="sales" /></span> : <Glyph kind={c.k} />}<span className="label">{c.label}</span></dt>
124	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
125	        </div>
126	      ))}
127	    </dl>
128	  );
129	}
130	
131	/* ------------------------------------------------------------------------------------------- key */
132	function Key(p: { points: PointsPayload; position: number; dim: Dim; isolate: Set<number>; onDim: (d: Dim) => void; onToggle: (v: number) => void; onClear: () => void }) {
133	  const values = p.points.dict[p.dim] as (string | null)[];
134	  const counts = useMemo(() => {
135	    const col = p.points.cols[p.dim], cps = p.points.cols.cp;
136	    const vis = new Array(values.length).fill(0);
137	    for (let i = 0; i < col.length; i++) if (col[i] >= 0 && cps[i] <= p.position) vis[col[i]]++;
138	    return vis as number[];
139	  }, [p.points, p.dim, p.position, values.length]);
140	  const max = Math.max(1, ...counts);
141	  return (
142	    <nav className="key" aria-label="Filter comments">
143	      <div className="key-dims" role="tablist">
144	        {DIMS.map((d) => <button key={d.id} role="tab" aria-selected={p.dim === d.id} onClick={() => p.onDim(d.id)}>{d.name}</button>)}
145	      </div>
146	      <ul className="key-values">
147	        {values.map((v, i) => {
148	          const n = counts[i];
149	          if (!n) return null;
150	          const on = p.isolate.size === 0 || p.isolate.has(i);
151	          return (
152	            <li key={i}>
153	              <button aria-pressed={p.isolate.has(i)} data-dim={on ? undefined : ""} onClick={() => p.onToggle(i)}>
154	                <span className="key-name">{valueName(p.dim, v)}</span>
