// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
// At rest every contact is white: held contacts (known at the earlier checkpoint) are dots, contacts this sweep
// acquired are rings. Blue is spent only on the sweep itself, the flare as it passes, hover and the locked contact.
// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Billboard, Html, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import type { PointsPayload, Selection, SourcesPayload } from "@/lib/types";
import { CARS, CAR_NAME, MARKET_NAME, R, SWEEP_START, TAU, TIME_START, polar, sector, timeAngle } from "./layout";

const VERT = /* glsl */ `
attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
const float TAU = 6.2831853;
void main() {
  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
  float passed = step(d, uSweep);
  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) * (1.0 - pow(uSweep, 12.0)) : 0.0;
  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  float depth = smoothstep(3.2, 7.5, -mv.z);           // far contacts recede
  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
}`;
const FRAG = /* glsl */ `
uniform vec3 uColor;
varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
void main() {
  float r = length(gl_PointCoord - 0.5);
  if (r > 0.5) discard;
  float dot = smoothstep(0.5, 0.3, r);
  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
  float a = mix(dot, ring, vRing * (1.0 - vFlare));
  vec3 col = mix(uColor, vec3(1.0), max(vFlare, vHov));
  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a);
}`;

// One colour per raw data type (validated categorical palette on black, dataviz reference dark steps).
export const TYPE_COLOR = { comment: "#3987e5", research: "#d95926", study: "#199e70", option: "#c98500", sales: "#d55181" } as const;

function contactMaterial(scale: number, color: string) {
  return new THREE.ShaderMaterial({
    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
    uniforms: {
      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 }, uColor: { value: new THREE.Color(color) },
    },
  });
}

function attrGeometry(pos: Float32Array, attrs: Record<string, Float32Array>) {
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
      <group ref={sweepRef} visible={false}><SweepBlade /></group>
      {p.locked && <Reticle at={p.locked} />}
    </>
  );
}

/* ------------------------------------------------------------------------------------------- sweep + lock */
function SweepBlade() {
  const mat = useMemo(() => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
  }), []);
  return (
    <>
      <mesh material={mat} position={[R.time / 2 + 0.1, 0, 0]}><planeGeometry args={[R.time + 0.2, 1.4]} /></mesh>
      <mesh position={[(R.time + 0.2) / 2, 0, 0]}><boxGeometry args={[R.time + 0.2, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
    </>
  );
}

function Reticle({ at }: { at: [number, number, number] }) {
  const ref = useRef<THREE.Group>(null);
  useFrame(({ clock }) => { if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.8; });
  return (
    <Billboard position={at}>
      <group ref={ref}>
        {[0, 1, 2, 3].map((k) => (
          <mesh key={k} rotation={[0, 0, (k * Math.PI) / 2]}>
            <ringGeometry args={[0.045, 0.052, 16, 1, -0.45, 0.9]} />
            <meshBasicMaterial color="#ffffff" transparent opacity={0.95} depthTest={false} />
          </mesh>
        ))}
      </group>
    </Billboard>
  );
}

/* ------------------------------------------------------------------------------------------- source rings */
function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

const RING_BEARING = Math.PI / 2; // the gap between the 1 Series and 5 Series sectors faces the viewer
const RINGS: { r: number; name: string; color: string }[] = [
  { r: R.study, name: "Study", color: TYPE_COLOR.study }, { r: R.options, name: "Options", color: TYPE_COLOR.option },
  { r: R.sales, name: "Sales", color: TYPE_COLOR.sales }, { r: R.time, name: "Research", color: TYPE_COLOR.research },
];

function Rings({ sources, onHover, onSelect, setCursor }: {
  sources: SourcesPayload | undefined;
  onHover: (h: Hover | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
  setCursor: (on: boolean) => void;
}) {
  const lines = useMemo(() => {
    const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
    const out: THREE.Line[] = [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide)));
    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
    time.computeLineDistances();
    out.push(time);
    return out;
  }, []);
// Bottom-right sweep control: the two checkpoints as nodes on one track. The later node shows what its sweep did
// to the earlier one's tracks (held / new), so "JUL builds on JAN" is visible, not just stated.
import { useCheckpoint, CHECKPOINT_ORDER } from "@/state/checkpoint";
import type { Checkpoint, CheckpointId } from "@/lib/types";
import "./sweep.css";

const fmt = (n: number | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));

export function SweepControl() {
  const { cp, setCp, checkpoints, sweepId } = useCheckpoint();
  const byId = Object.fromEntries((checkpoints ?? []).map((c) => [c.id, c]));
  // Same three groups as the readout (comments, research, BMW data), so held + new = the readout totals.
